export const getListDailyLoopRunsUrl = () => {




  return `/api/daily-loop/runs`
}

/**
 * @summary List daily loop runs and reports
 */
export const listDailyLoopRuns = async ( options?: RequestInit): Promise<DailyLoopRun[]> => {

  return customFetch<DailyLoopRun[]>(getListDailyLoopRunsUrl(),
  {
    ...options,
    method: 'GET'


  }
);}





export const getListDailyLoopRunsQueryKey = () => {
    return [
    `/api/daily-loop/runs`
    ] as const;
    }


export const getListDailyLoopRunsQueryOptions = <TData = Awaited<ReturnType<typeof listDailyLoopRuns>>, TError = ErrorType<unknown>>( options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof listDailyLoopRuns>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getListDailyLoopRunsQueryKey();



    const queryFn: QueryFunction<Awaited<ReturnType<typeof listDailyLoopRuns>>> = ({ signal }) => listDailyLoopRuns({ signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof listDailyLoopRuns>>, TError, TData> & { queryKey: QueryKey }
}

export type ListDailyLoopRunsQueryResult = NonNullable<Awaited<ReturnType<typeof listDailyLoopRuns>>>
export type ListDailyLoopRunsQueryError = ErrorType<unknown>


/**
 * @summary List daily loop runs and reports
 */

export function useListDailyLoopRuns<TData = Awaited<ReturnType<typeof listDailyLoopRuns>>, TError = ErrorType<unknown>>(
  options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof listDailyLoopRuns>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getListDailyLoopRunsQueryOptions(options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return withQueryKey(query, queryOptions.queryKey);
}







